export const GetPublicProfileParams = zod.object({
  "username": zod.coerce.string()
})

export const GetPublicProfileResponse = zod.object({
  "username": zod.string(),
  "name": zod.string(),
  "avatarUrl": zod.string().nullish(),
  "bio": zod.string().nullish(),
  "location": zod.string().nullish(),
  "college": zod.string().nullish(),
  "overallScore": zod.number(),
  "skills": zod.array(zod.object({
  "id": zod.number(),
  "name": zod.string(),
  "category": zod.string(),
  "score": zod.number(),
  "confidence": zod.enum(['low', 'medium', 'high']),
  "improvementSuggestion": zod.string().nullish(),
  "color": zod.string().nullable()
})),
  "projects": zod.array(zod.object({
  "id": zod.number(),
  "name": zod.string(),
  "description": zod.string().nullish(),
  "language": zod.string().nullable(),
  "stars": zod.number(),
  "difficulty": zod.enum(['beginner', 'intermediate', 'advanced', 'expert']),
  "score": zod.number(),
  "techStack": zod.array(zod.string()).optional(),
  "htmlUrl": zod.string().nullish()
})),
  "githubProfile": zod.object({
  "id": zod.number(),
  "username": zod.string(),
  "avatarUrl": zod.string().nullish(),
  "bio": zod.string().nullish(),
  "totalRepos": zod.number(),
  "stars": zod.number(),
  "forks": zod.number(),
  "followers": zod.number(),
  "following": zod.number(),
  "commits": zod.number(),
  "pullRequests": zod.number(),
  "issues": zod.number(),
  "score": zod.number(),
  "topLanguage": zod.string().nullish(),
  "weeklyHours": zod.number().nullish(),
  "trendingRepo": zod.string().nullish()
}),
  "codingProfiles": zod.array(zod.object({
  "id": zod.number(),
  "platform": zod.enum(['leetcode', 'codeforces', 'codechef', 'hackerrank', 'geeksforgeeks', 'atcoder']),
  "username": zod.string(),
  "problemsSolved": zod.number(),
  "rating": zod.number().nullable(),
  "rank": zod.string().nullable(),
  "streak": zod.number().nullish(),
  "easyCount": zod.number().nullish(),
  "mediumCount": zod.number().nullish(),
  "hardCount": zod.number().nullish(),
  "badges": zod.number().optional(),
  "lastSynced": zod.string().nullish()
})).optional(),
  "badges": zod.array(zod.object({
  "id": zod.number(),
  "name": zod.string(),
  "description": zod.string(),
  "icon": zod.string(),
  "earnedAt": zod.string(),
  "rarity": zod.enum(['common', 'rare', 'epic', 'legendary']).optional()
})).optional()
})


